create or replace function public.tour_for_match(target_match uuid) returns uuid language sql stable security definer set search_path=public as $$ select r.tour_id from public.matches m join public.rounds r on r.id=m.round_id where m.id=target_match; $$;
create or replace function public.audit_score_change() returns trigger language plpgsql security definer set search_path=public as $$ declare match_id_value uuid;entity_uuid uuid; begin match_id_value:=coalesce(new.match_id,old.match_id); entity_uuid:=coalesce(new.id,old.id); insert into public.audit_log(tour_id,actor_user_id,entity_type,entity_id,action,old_data,new_data) values(public.tour_for_match(match_id_value),(select auth.uid()),tg_table_name,entity_uuid,tg_op,to_jsonb(old),to_jsonb(new)); return coalesce(new,old); end;$$;
create trigger audit_hole_scores after insert or update or delete on public.hole_scores for each row execute function public.audit_score_change(); create trigger audit_team_hole_scores after insert or update or delete on public.team_hole_scores for each row execute function public.audit_score_change(); create trigger audit_selected_drives after insert or update or delete on public.selected_drives for each row execute function public.audit_score_change(); create trigger audit_match_confirmations after insert or update or delete on public.match_confirmations for each row execute function public.audit_score_change();
